export type TypeControle = 'INTERNE' | 'EXTERNE';
export type Decision     = 'EN_ATTENTE' | 'VALIDE' | 'REFUSE' | 'MODIFICATION_DEMANDEE';

export const DECISION_META: Record<Decision, { label: string; color: string; icon: string }> = {
  EN_ATTENTE:            { label: 'En attente',            color: '#B45309', icon: 'hourglass_empty' },
  VALIDE:                { label: 'Validé',                color: '#15803D', icon: 'check_circle'    },
  REFUSE:                { label: 'Refusé',                color: '#B91C1C', icon: 'cancel'          },
  MODIFICATION_DEMANDEE: { label: 'Modification demandée', color: '#1D4ED8', icon: 'edit_note'       },
};

export interface Commentaire {
  auteurId: string;
  contenu: string;
  date: string;
}

export interface Controle {
  id: string;
  planId: string;
  versionId: string;
  typeControle: TypeControle;
  controleurId: string;
  dateControle: string;
  decision: Decision;
  remarque?: string;
  commentaires: Commentaire[];
}
